// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount, address user) public {
        vm.assume(user != address(0));
        vm.assume(amount <= address(c).balance);
        uint256 minDepositBefore = c.MinDeposit();
        // Fund the user with enough ETH
        vm.deal(user, 2 ether);
        // First make a deposit so the user has balance to cash out
        vm.prank(user);
        c.Deposit{value: 1 ether}();
        // Now call CashOut
        vm.prank(user);
        (bool success,) = address(c).call(abi.encodeWithSignature("CashOut(uint256)", amount));
        // In the reference, CashOut can revert if amount > balance; we don't revert test on that
        if (success) {
            uint256 minDepositAfter = c.MinDeposit();
            assertTrue(minDepositAfter == minDepositBefore);
        } else {
            // If it reverted, MinDeposit should still be unchanged
            uint256 minDepositAfter = c.MinDeposit();
            assertTrue(minDepositAfter == minDepositBefore);
        }
    }
}

